@font-face {
  font-family: "Segment7Standard";
  font-style: italic;
  font-weight: 400;
  src: url("data:font/opentype;charset=utf-8;base64,") format("opentype");
}
body, html {
  height: 100%;
  min-height: 100%;
  position: relative;
  -webkit-tap-highlight-color: rgba(0, 0, 0, 0);
  -webkit-touch-callout: none;
  -webkit-text-size-adjust: 100%;
  -ms-text-size-adjust: 100%;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  margin: 0;
  padding: 0;
  background-color: #eee;
  overflow: hidden;
}

tb-root {
  margin: 0;
  width: 100%;
  min-height: 100%;
  height: 100%;
  display: flex;
  flex-direction: row;
  box-sizing: border-box;
}

/***************
 * TYPE DEFAULTS
 ***************/
body,
button,
html,
input,
select,
textarea,
td,
th {
  font-family: Roboto, "Helvetica Neue", sans-serif;
  font-size: 16px;
}

body {
  line-height: normal;
}

a {
  font-weight: 400;
  color: #106cc8;
  text-decoration: none;
  border-bottom: 1px solid rgba(64, 84, 178, 0.25);
  transition: border-bottom 0.35s;
}

a:hover,
a:focus {
  border-bottom: 1px solid #4054b2;
}

h1, h1.mat-headline,
h2,
h2.mat-headline,
h3,
h3.mat-headline,
h4,
h4.mat-headline,
h5,
h5.mat-headline,
h6,
h6.mat-headline {
  margin-top: 1rem;
  margin-bottom: 1rem;
}

h1 {
  font-size: 3.4rem;
  font-weight: 400;
  line-height: 4rem;
}

h2 {
  font-size: 2.4rem;
  font-weight: 400;
  line-height: 3.2rem;
}

h3 {
  font-size: 2rem;
  font-weight: 500;
  letter-spacing: 0.005em;
}

h4 {
  font-size: 1.6rem;
  font-weight: 400;
  line-height: 2.4rem;
  letter-spacing: 0.01em;
}

p {
  margin: 0.8em 0 1.6em;
  font-size: 1.6rem;
  font-weight: 400;
  line-height: 1.6em;
  letter-spacing: 0.01em;
}

strong {
  font-weight: 500;
}

blockquote {
  padding-left: 16px;
  margin-left: 0;
  font-style: italic;
  border-left: 3px solid rgba(0, 0, 0, 0.12);
}

fieldset {
  padding: 0;
  margin: 0;
  border: none;
}

section.tb-header-buttons {
  position: absolute;
  top: 86px;
  right: 0;
  z-index: 3;
  pointer-events: none;
}
@media screen and (min-width: 960px) {
  section.tb-header-buttons {
    top: 86px;
  }
}
section.tb-header-buttons .tb-btn-header {
  margin: 6px 8px;
  position: relative !important;
  display: inline-block !important;
  animation: tbMoveFromTopFade 0.3s ease both;
}
section.tb-header-buttons .tb-btn-header.tb-hide {
  animation: tbMoveToTopFade 0.3s ease both;
}

section.tb-footer-buttons {
  position: fixed;
  right: 20px;
  bottom: 20px;
  z-index: 30;
  pointer-events: none;
}
section.tb-footer-buttons .tb-btn-footer {
  margin: 6px 8px;
  position: relative !important;
  display: inline-block !important;
  animation: tbMoveFromBottomFade 0.3s ease both;
}
section.tb-footer-buttons .tb-btn-footer.tb-hide {
  animation: tbMoveToBottomFade 0.3s ease both;
}

.tb-details-buttons button {
  margin: 6px 8px;
}

label.tb-title {
  padding-bottom: 15px;
  font-size: 13px;
  font-weight: 400;
  color: #666;
  pointer-events: none;
}
label.tb-title.no-padding {
  padding-bottom: 0;
}
label.tb-title.tb-required::after {
  font-size: 13px;
  color: rgba(0, 0, 0, 0.54);
  vertical-align: top;
  content: " *";
}
label.tb-title.tb-error {
  color: #dd2c00;
}
label.tb-title.tb-error.tb-required::after {
  color: #dd2c00;
}
label.tb-small {
  font-size: 12px;
  color: rgba(0, 0, 0, 0.54);
  pointer-events: none;
}

.tb-noselect {
  user-select: none;
}

.tb-readonly-label {
  color: rgba(0, 0, 0, 0.54);
}

.tb-disabled-label {
  color: rgba(0, 0, 0, 0.44);
}

div.tb-small {
  font-size: 14px;
  color: rgba(0, 0, 0, 0.54);
}

.tb-hint {
  padding-bottom: 15px;
  font-size: 12px;
  line-height: 14px;
  color: #808080;
}

.mat-caption.tb-required::after {
  font-size: 10px;
  color: rgba(0, 0, 0, 0.54);
  vertical-align: top;
  content: " *";
}

pre.tb-highlight {
  display: block;
  padding: 15px;
  margin: 20px 0;
  overflow-x: auto;
  background-color: #f7f7f7;
}
pre.tb-highlight code {
  box-sizing: border-box;
  display: inline-block;
  padding: 0;
  font-family: monospace;
  font-size: 16px;
  font-weight: 700;
  color: #303030;
  vertical-align: bottom;
}

.tb-notice {
  padding: 15px;
  font-size: 16px;
  background-color: #f7f7f7;
  border: 1px solid #ccc;
}

.ace_editor {
  font-size: 16px !important;
}

.tb-timewindow-panel, .tb-legend-config-panel {
  overflow: hidden;
  background: #fff;
  border-radius: 4px;
  box-shadow: 0 7px 8px -4px rgba(0, 0, 0, 0.2), 0 13px 19px 2px rgba(0, 0, 0, 0.14), 0 5px 24px 4px rgba(0, 0, 0, 0.12);
}

.tb-panel-actions {
  margin-bottom: 0;
  padding: 8px 8px 8px 16px;
}
.tb-panel-actions .mat-button + .mat-button,
.tb-panel-actions .mat-button + .mat-raised-button,
.tb-panel-actions .mat-raised-button + .mat-button,
.tb-panel-actions .mat-raised-button + .mat-raised-button {
  margin-left: 8px;
}

