  position: relative;
  padding: 10px 0;
  margin-top: 32px;
}

.tb-prompt {
  display: flex;
  font-size: 18px;
  font-weight: 400;
  line-height: 18px;
  color: rgba(0, 0, 0, 0.38);
}
.tb-prompt.required {
  color: #dd2c00;
}

.tb-fullscreen {
  position: fixed !important;
  top: 0;
  left: 0;
  width: 100% !important;
  height: 100% !important;
}

.tb-fullscreen-parent {
  background: #eee;
  z-index: 0;
}

