.tb-error-messages {
  height: 24px;
  margin-top: -6px;
}

.tb-error-message {
  transition: all 0.3s cubic-bezier(0.55, 0, 0.55, 0.2);
  padding: 10px 0 0 10px;
  overflow: hidden;
  font-size: 12px;
  line-height: 14px;
  color: #dd2c00;
}

.tb-autocomplete .mat-option {
  display: block;
  line-height: 24px;
  height: auto !important;
  padding-top: 8px;
  border-bottom: 1px solid #eee;
  font-size: 14px;
}
.tb-autocomplete .mat-option .mat-option-text {
  line-height: 24px;
  height: auto !important;
  white-space: normal !important;
}
.tb-autocomplete .mat-option.tb-not-found {
  padding: 0;
  border-bottom: none;
}
