.tb-ace-doc-tooltip code {
  color: #444;
}
.tb-ace-doc-tooltip code.title {
  font-size: 14px;
}
.tb-ace-doc-tooltip div.tb-function-info {
  font-size: 14px;
}
.tb-ace-doc-tooltip div.tb-function-return {
  font-size: 1rem;
  letter-spacing: 0.03rem;
  color: #444;
